#include <iostream>
using namespace std;
double power(double x, int p, int& calls) {
    calls++;
    if (p == 0) return 1;
    if (p == 1) return x;
    double t = power(x, p / 2, calls);
    return p % 2 ? x * t * t : t * t;
}
int main() { int calls = 0; cout << power(2, 10, calls) << " " << calls << endl; }

