#include <iostream>
using namespace std;
int main() {
    const int N = 30;
    bool hop[N + 1] = {};
    for (int i = 2; i * i <= N; i++)
        if (!hop[i])
            for (int j = i * i; j <= N; j += i) hop[j] = true;
    int dem = 0, last = 0;
    for (int i = 2; i <= N; i++) if (!hop[i]) { dem++; last = i; }
    cout << dem << " " << last << endl;
}

