#include <cstdio>
#include <iostream>
using namespace std;
double power(double x, int p) {
    if (p < 0) return 1 / power(x, -p);
    if (p == 0) return 1;
    if (p == 1) return x;
    double t = power(x, p / 2);
    return p % 2 ? x * t * t : t * t;
}
int main() { printf("%.4f %.4f\n", power(2, -3), power(2, 0)); }

